def has_trailing_zeros(nums):
    # Count number of even numbers (those with at least one trailing zero)
    even_count = 0
    for num in nums:
        if num % 2 == 0:
            even_count += 1
        # Early return: as soon as we find two evens, answer is True
        if even_count >= 2:
            return True
    # Not enough even numbers for a valid pair
    return False
